  "INSERT INTO \"certificates\" (\"id\", \"title\", \"code\", \"issuer\", \"issued_date\", \"expiry_date\", \"image_id\", \"file_id\", \"scope\", \"summary\", \"order_num\", \"updated_at\", \"created_at\") VALUES (1, 'Chứng nhận Sản phẩm OCOP 4 Sao - Rau Ăn Quả Túy Loan', 'OCOP-DN-4S-2023-018', 'Ủy ban Nhân dân Thành phố Đà Nẵng', '2023-12-15T00:00:00.000Z', '2026-12-15T00:00:00.000Z', 1, NULL, 'Nhóm sản phẩm rau ăn quả: Khổ qua Túy Loan, bí đao chanh, mướp hương, dưa leo giống Nhật, đậu cô ve', 'Sản phẩm OCOP 4 sao tiêu biểu của TP. Đà Nẵng, đáp ứng nghiêm ngặt các tiêu chí an toàn vệ sinh thực phẩm, truy xuất nguồn gốc và bảo vệ môi trường sinh thái.', 100, '2026-08-21T07:53:26.581Z', '2026-08-21T07:53:26.580Z') ON CONFLICT (\"id\") DO UPDATE SET \"title\" = EXCLUDED.\"title\", \"code\" = EXCLUDED.\"code\", \"issuer\" = EXCLUDED.\"issuer\", \"issued_date\" = EXCLUDED.\"issued_date\", \"expiry_date\" = EXCLUDED.\"expiry_date\", \"image_id\" = EXCLUDED.\"image_id\", \"file_id\" = EXCLUDED.\"file_id\", \"scope\" = EXCLUDED.\"scope\", \"summary\" = EXCLUDED.\"summary\", \"order_num\" = EXCLUDED.\"order_num\", \"updated_at\" = EXCLUDED.\"updated_at\", \"created_at\" = EXCLUDED.\"created_at\";",
