  "INSERT INTO \"certificates\" (\"id\", \"title\", \"code\", \"issuer\", \"issued_date\", \"expiry_date\", \"image_id\", \"file_id\", \"scope\", \"summary\", \"order_num\", \"updated_at\", \"created_at\") VALUES (3, 'Giấy Chứng Nhận Thực Hành Nông Nghiệp Tốt VietGAP', 'VietGAP-TT-14-04-48-0012', 'Chi cục Quản lý Chất lượng Nông Lâm sản và Thủy sản Đà Nẵng', '2024-03-20T00:00:00.000Z', '2027-03-20T00:00:00.000Z', 1, NULL, 'Vùng sản xuất và sơ chế 8 ha rau, củ, quả an toàn tại xã Hòa Phong, huyện Hòa Vang, TP. Đà Nẵng', 'Chứng nhận toàn bộ quy trình canh tác từ đất, nước tưới sông Túy Loan, hạt giống, phân vi sinh ủ hoai và quản lý dịch hại sinh học IPM đạt chuẩn VietGAP quốc gia.', 80, '2026-08-21T07:53:26.601Z', '2026-08-21T07:53:26.601Z') ON CONFLICT (\"id\") DO UPDATE SET \"title\" = EXCLUDED.\"title\", \"code\" = EXCLUDED.\"code\", \"issuer\" = EXCLUDED.\"issuer\", \"issued_date\" = EXCLUDED.\"issued_date\", \"expiry_date\" = EXCLUDED.\"expiry_date\", \"image_id\" = EXCLUDED.\"image_id\", \"file_id\" = EXCLUDED.\"file_id\", \"scope\" = EXCLUDED.\"scope\", \"summary\" = EXCLUDED.\"summary\", \"order_num\" = EXCLUDED.\"order_num\", \"updated_at\" = EXCLUDED.\"updated_at\", \"created_at\" = EXCLUDED.\"created_at\";",
  "INSERT INTO \"certificates\" (\"id\", \"title\", \"code\", \"issuer\", \"issued_date\", \"expiry_date\", \"image_id\", \"file_id\", \"scope\", \"summary\", \"order_num\", \"updated_at\", \"created_at\") VALUES (4, 'Phiếu Kết Quả Kiểm Nghiệm Đất, Nước & Dư Lượng Thuốc BVTV', 'KN-ATTP-DN-2026-88', 'Trung tâm Kỹ thuật Tiêu chuẩn Đo lường Chất lượng Đà Nẵng', '2026-01-10T00:00:00.000Z', '2027-01-10T00:00:00.000Z', 1, NULL, 'Phân tích mẫu đất canh tác, mẫu nước sông Túy Loan và mẫu rau thành phẩm', 'Kết quả 100% mẫu kiểm nghiệm đạt chỉ số an toàn tuyệt đối: Không phát hiện kim loại nặng vượt ngưỡng, 0% dư lượng thuốc bảo vệ thực vật hóa học.', 70, '2026-08-21T07:53:26.612Z', '2026-08-21T07:53:26.612Z') ON CONFLICT (\"id\") DO UPDATE SET \"title\" = EXCLUDED.\"title\", \"code\" = EXCLUDED.\"code\", \"issuer\" = EXCLUDED.\"issuer\", \"issued_date\" = EXCLUDED.\"issued_date\", \"expiry_date\" = EXCLUDED.\"expiry_date\", \"image_id\" = EXCLUDED.\"image_id\", \"file_id\" = EXCLUDED.\"file_id\", \"scope\" = EXCLUDED.\"scope\", \"summary\" = EXCLUDED.\"summary\", \"order_num\" = EXCLUDED.\"order_num\", \"updated_at\" = EXCLUDED.\"updated_at\", \"created_at\" = EXCLUDED.\"created_at\";",
